//primes for hashing 937,991,1013,1409,1741

void solve() {
    ll x,y,n,maxi,mini,meow;
    cin>>x>>y>>n;
    set <pii> s;
    rep(i,1,n+1){
    	mini=((x*i)/y);
    	maxi=ceil((x*i*1.0)/(y*1.0));
    	if ((mini+maxi)*y>2*x*i){
    		meow=__gcd(i,mini);
    		s.insert({i/meow,mini/meow});
    	}
    	else {
    		meow=__gcd(i,maxi);
    		s.insert({i/meow,maxi/meow});
    	}
    }
    ll q=(*s.begin()).F;
    ll p=(*s.begin()).S;
    for (auto i:s){
    	if ((i.S)*y==x*(i.F)){
    		p=i.S;
    		q=i.F;
    	}
    	else if (((i.S)*y>(i.F)*x) && (p*y>x*q)){
    		if ((i.S)*q<(p*(i.F))){
    			p=i.S;
    			q=i.F;
    		}
    	}
    	else if (((i.S)*y<(i.F)*x) && (p*y>x*q)){
    		if (2*x*q*(i.F)<y*((p*(i.F)) + (q*(i.S)))){
    			p=i.S;
    			q=i.F;
    		}
    	}
    	else if (((i.S)*y>(i.F)*x) && (p*y<x*q)){
    		if (2*x*q*(i.F)>y*((p*(i.F)) + (q*(i.S)))){
    			p=i.S;
    			q=i.F;
    		}
    	}
    	else if (((i.S)*y<(i.F)*x) && (p*y<x*q)) {
    		if ((i.S)*q>(p*(i.F))){
    			p=i.S;
    			q=i.F;
    		}
    	}
    }
    meow=__gcd(p,q);
    cout<<p/meow<<'/'<<q/meow<<endl;
}

